func _step() -> void:
	if done or not is_world_visible():
		return
	var mv: Node = _hero.get_component("Movement")
	if mv == null:
		_finish()
		return
	# Кадр движения: путь идёт сам, ждём прибытия.
	if mv.is_moving():
		return

	var progress := false

	# 1) У ресурсного узла — собрать (через игровую цепочку).
	var res_cell: Vector2i = _nearest_resource()
	if res_cell == Vector2i(-1, -1):
		_end_turn()
		return
	if mv.get_current_cell() == res_cell:
		var collected: bool = _try_collect_at(res_cell)
		_action_fails = 0
		progress = collected
	else:
		# 2) Дойти до ближайшего узла; если не сдвинулся — дожить ход.
		#    (Баланс-проба: герой должен дожить MAX_TURNS ходов.)
		var was_cell: Vector2i = mv.get_current_cell()
		if mv.move_to_cell(res_cell):
			# Путь к узлу начат (headless: шаг/кадр). Прибытие и сбор —
			# в следующем кадре, когда is_moving снова false.
			_action_fails = 0
			progress = true
		else:
			_end_turn()
			return

	if not progress:
		_action_fails += 1
		if _action_fails >= STUCK_LIMIT:
			# Узлы кончились или герой не может двинуться — доживать до конца.
			_action_fails = 0
			_end_turn()
		return

